INSERT INTO `wf_logic_flow` (`id`, `created_at`, `description`, `dsl_json`, `flow_key`, `name`, `status`, `tenant_id`, `updated_at`, `version`) VALUES ('fbefdda018464d64ad24fbda9ecc349e', '2026-10-11 16:06:32.813624', '演示：登记领用单(新增)后自动扣减物料库存(DATA_UPDATE SUB)并写入领用流水(DATA_INSERT)', '{"nodes": [{"id": "start1", "type": "START", "name": "开始", "x": 120, "y": 160}, {"id": "du_stock", "type": "DATA_UPDATE", "name": "扣减物料库存", "x": 350, "y": 160, "config": {"table": "wf_biz_material_stock_demo", "setOps": [{"column": "stockQty", "mode": "SUB", "value": "{{formData.qty}}"}], "where": [{"column": "productCode", "op": "EQ", "value": "{{formData.productCode}}"}]}}, {"id": "di_log", "type": "DATA_INSERT", "name": "写入领用流水", "x": 590, "y": 160, "config": {"formKey": "pickup_log_demo", "data": [{"column": "productCode", "value": "{{formData.productCode}}"}, {"column": "productName", "value": "{{formData.productName}}"}, {"column": "qty", "value": "{{formData.qty}}"}, {"column": "pickupBy", "value": "{{formData.pickupBy}}"}, {"column": "sourceNote", "value": "来源领用单 {{dataId}}"}]}}, {"id": "end1", "type": "END", "name": "结束", "x": 820, "y": 160}], "edges": [{"id": "e1", "source": "start1", "target": "du_stock"}, {"id": "e2", "source": "du_stock", "target": "di_log"}, {"id": "e3", "source": "di_log", "target": "end1"}]}', 'pickup_stock_sync', '领用登记联动库存与流水', 'PUBLISHED', 'default', '2026-10-11 16:21:55.655742', '9') ON DUPLICATE KEY UPDATE `created_at`=VALUES(`created_at`), `description`=VALUES(`description`), `dsl_json`=VALUES(`dsl_json`), `flow_key`=VALUES(`flow_key`), `name`=VALUES(`name`), `status`=VALUES(`status`), `tenant_id`=VALUES(`tenant_id`), `updated_at`=VALUES(`updated_at`), `version`=VALUES(`version`);
